  const maps = Object.fromEntries(locales.map((locale) => [locale, new Map()]));
  rows.forEach((row) => locales.forEach((locale, i) => maps[locale].set(row[0], row[i])));
  let staticNodes = [], staticAttributes = [];
  const get = (key) => { try { return localStorage.getItem(key); } catch { return null; } };
  const set = (key, value) => { try { localStorage.setItem(key, value); } catch { /* Optional preference, no private data. */ } };
  const valid = (locale) => locales.includes(locale);
  function initialLocale() {
    const saved = get("frequency.locale"); if (valid(saved)) return saved;
    const language = navigator.language?.toLowerCase() || "pt";
    return language.startsWith("es") ? "es-BO" : language.startsWith("zh") ? "zh-CN" : language.startsWith("hi") ? "hi-IN" : language.startsWith("en") ? "en-US" : "pt-BR";
  }
  return {
    initialLocale,
    userLocale(id, fallback) { const saved = get(`frequency.locale.user.${id}`); return valid(saved) ? saved : valid(fallback) ? fallback : initialLocale(); },
    saveLocale(locale, id) { if (!valid(locale)) return; set("frequency.locale", locale); if (id) set(`frequency.locale.user.${id}`, locale); },
    translate(locale, source, spanish = {}) { return maps[locale]?.get(source) || (locale === "es-BO" ? spanish[source] : null) || source; },
    captureStatic() {
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      while (walker.nextNode()) {
        const node = walker.currentNode;
        if (node.parentElement.closest("script,style,[data-no-translate]")) continue;
        const value = node.nodeValue; if (value.trim()) staticNodes.push([node, value]);
      }
      document.querySelectorAll("[placeholder],[aria-label],[title],[alt]").forEach((node) => ["placeholder", "aria-label", "title", "alt"].forEach((attr) => { if (node.getAttribute(attr)) staticAttributes.push([node, attr, node.getAttribute(attr)]); }));
    },
    renderStatic(translate) {
      staticNodes.forEach(([node, value]) => { if (node.isConnected) node.nodeValue = value.replace(value.trim(), translate(value.trim())); });
      staticAttributes.forEach(([node, attr, value]) => { if (node.isConnected) node.setAttribute(attr, translate(value)); });
    },
  };
